output_text:
[
  {
    "id": "h1_pedestrian_only_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "h2_no_cart_entry_to_single_file_aisle",
    "text": "A shopper must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisle": {
          "pre": "MOVE",
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterSingleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "h3_cart_drop_only_at_aisle_mouths",
    "text": "Carts may only be set down at designated wide aisle mouths before entering a narrow shelf aisle.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "h4_retrieve_parked_cart",
    "text": "After parking a cart at a narrow-aisle mouth, the shopper is obliged to retrieve it before leaving the store.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCartAtMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickupCartAtMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCartAtMouth",
      "discharge": "pickupCartAtMouth"
    }
  },
  {
    "id": "h5_cart_required_in_wide_shared_aisles",
    "text": "Except in the entry/cart area, at aisle mouths, or inside single-file aisles, shoppers should not move through shared wide aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "entryCartZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideSharedAisle": {
          "or": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          "wideSharedAisle",
          {
            "not": "singleFileShelfAisle"
          },
          {
            "not": "entryCartZone"
          },
          {
            "not": "cartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "h6_cartless_shelf_interactions_only_in_single_file_aisles",
    "text": "Shelf interactions without a cart are permitted only in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "hasCart"
          },
          "adjShelf",
          {
            "not": "singleFileShelfAisle"
          }
        ]
      }
    }
  },
  {
    "id": "h7_single_file_entry_implies_shopping_not_shortcut",
    "text": "If a shopper enters a single-file shelf aisle on foot, they are obliged to use it for a shelf interaction before leaving the trip unfinished.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              "cartParkingMouth"
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": "singleFileShelfInteraction"
    }
  },
  {
    "id": "h8_one_way_aisle_flow_no_west",
    "text": "Customer aisles follow one-way traffic, so shoppers must not move west along them.",
    "abstraction": {
      "state_properties": {
        "customerAisle": {
          "or": [
            {
              "ge": [
                "freeWidthH",
                2
              ]
            },
            {
              "ge": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "customerAisle"
        ]
      }
    }
  }
]
